{
  "name": "send_hci_vendor_event_0x7c",
  "confidence": "medium",
  "docstring": "Allocates an HCI event buffer, updates RF/5G switch configuration state, and sends the vendor event response.",
  "subsystem": "bt",
  "var_renames": {
    "a2": "cmd_params",
    "a1a": "extracted_info",
    "v5": "evt_buf",
    "v6": "vendor_info",
    "v7": "rf_info",
    "v8": "sw_en",
    "v9": "status"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "cmd_params byte 0: nonzero requests driver start, zero requests driver stop"
    },
    {
      "offset": 1,
      "meaning": "cmd_params byte 1: selects whether vendor_info or cmd_params byte 2 is used"
    },
    {
      "offset": 2,
      "meaning": "cmd_params byte 2: fallback mode/configuration byte"
    },
    {
      "offset": 3,
      "meaning": "cmd_params byte 3: if nonzero and driver start, sets 5G enable flag"
    },
    {
      "offset": 188,
      "meaning": "rf_info low byte at offset 0xbc: status/vendor byte reflected in event"
    },
    {
      "offset": 178,
      "meaning": "rf_info uint16 at offset 0xb2: bit 0x4000 used as 5G enable flag"
    }
  ]
}
